function model(p) {
  // Illustrative PHI flow for a readmission-risk use case. Three fictional members travel from the claims system
  // to analytics and an outside care-management vendor. A field exposure is a raw field present at a hop whose
  // purpose does not need it. Times are playback seconds for the explainer.
  const on = k => Math.round(p[k]) === 1;
  const SF = on('systemNames');
  const FIELDS = [
    { id: 'name', label: 'Member name', short: 'Name' }, { id: 'mid', label: 'Member ID', short: 'ID' },
    { id: 'dob', label: 'Date of birth', short: 'DOB' }, { id: 'addr', label: 'Address', short: 'Address' },
    { id: 'dx', label: 'Diagnosis codes', short: 'Diagnosis' }, { id: 'amt', label: 'Claim amount', short: 'Amount' },
    { id: 'prov', label: 'Provider', short: 'Provider' }
  ];
  const DEID = { name: 'token', mid: 'token', dob: 'age band', addr: 'region' };
  const MEMBERS = [
    { id: 1, name: 'Member 1', optedOut: false, token: '#7F3A', band: '65-69', region: 'North' },
    { id: 2, name: 'Member 2', optedOut: false, token: '#C21D', band: '70-74', region: 'Coast' },
    { id: 3, name: 'Member 3', optedOut: true, token: '#09BE', band: '60-64', region: 'Valley' }
  ];
  const ALL = FIELDS.map(f => f.id), UP = ['mid', 'dob', 'addr', 'dx', 'amt', 'prov'];
  // needs: raw fields the purpose uses; sources: raw fields kept only to derive a key, age band or region when not de-identified
  const HOPS = [
    { id: 'claims', g: 'Claims system', s: 'Health Cloud claims', gs: 'Claims', ss: 'Health Cloud', icon: 'file-text', from: -1,
      purpose: 'Adjudicate and pay the claim', needs: ALL, sources: [], role: 'the claims system' },
    { id: 'integration', g: 'Integration layer', s: 'MuleSoft', gs: 'Integration', ss: 'MuleSoft', icon: 'git-merge', from: 0,
      purpose: 'Carry claims to the data platform', needs: UP, sources: [], role: 'the integration layer' },
    { id: 'platform', g: 'Data platform', s: 'Data Cloud', gs: 'Platform', ss: 'Data Cloud', icon: 'database', from: 1,
      purpose: 'Unify claims for analytics and outreach', needs: UP, sources: [], role: 'the data platform' },
    { id: 'sandbox', g: 'Data science sandbox', s: 'Data science sandbox', gs: 'Sandbox', ss: 'Sandbox', icon: 'flask-conical', from: 2,
      purpose: 'Train the readmission risk model', needs: ['dx', 'amt', 'prov'], sources: ['mid', 'dob', 'addr'], analytics: true,
      derived: 'a member key, age band and region', role: 'the sandbox' },
    { id: 'dashboard', g: 'Analytics dashboard', s: 'CRM Analytics / Tableau', gs: 'Dashboard', ss: 'Tableau', icon: 'chart-column', from: 2,
      purpose: 'Show readmission risk by age band, region, diagnosis and provider', needs: ['dx', 'prov'], sources: ['dob', 'addr'], analytics: true,
      derived: 'an age band and region', role: 'the dashboard' },
    { id: 'vendor', g: 'Care-management vendor', s: 'Care-management vendor', gs: 'Vendor', ss: 'Vendor', icon: 'building-2', from: 2,
      purpose: 'Reach out to high-risk members under a business associate agreement', needs: ['mid', 'dx'], sources: [], gate: true, role: 'the vendor export' }
  ];
  function run(filt, deid, consent) {
    const hops = HOPS.map(h => ({ id: h.id, generic: h.g, label: SF ? h.s : h.g, short: SF ? h.ss : h.gs, icon: h.icon, purpose: h.purpose, from: h.from,
      analytics: !!h.analytics, gate: !!h.gate, derived: h.derived || '', role: h.role, needs: h.needs.join(' ') }));
    HOPS.forEach((h, i) => {
      hops[i].records = MEMBERS.map((mb, k) => {
        const up = h.from < 0 ? null : hops[h.from].records[k];
        const blocked = !!h.gate && consent && mb.optedOut;
        const need = h.gate && mb.optedOut ? [] : h.needs;   // no consent: outreach has no purpose for this member
        const cells = {};
        let exposures = 0;
        for (const f of ALL) {
          const c = { present: false, needed: need.includes(f), exposed: false, action: 'none', as: '' };
          if (up && !up.cells[f].present) c.action = 'absent';
          else if (blocked) c.action = 'blocked';
          else if (h.analytics && deid && DEID[f]) { c.action = 'tokenised'; c.as = DEID[f]; }
          else if (filt && !h.needs.includes(f) && !h.sources.includes(f)) c.action = 'dropped';
          else { c.present = true; c.exposed = !c.needed; }
          if (c.exposed) exposures++;
          cells[f] = c;
        }
        return { member: mb.id, optedOut: mb.optedOut, blocked, cells, exposures };
      });
      const groups = [];
      hops[i].records.forEach(r => {
        const sig = JSON.stringify(r.cells), g = groups.find(x => x.sig === sig);
        if (g) { g.members.push(r.member); g.count++; } else groups.push({ sig, members: [r.member], count: 1, cells: r.cells, exposures: r.exposures, blocked: r.blocked, optedOut: r.optedOut });
      });
      hops[i].groups = groups.map(g => ({ members: g.members.join(', '), count: g.count, cells: g.cells, exposures: g.exposures, weighted: g.exposures * g.count, blocked: g.blocked, optedOut: g.optedOut }));
      hops[i].exposures = hops[i].records.reduce((a, r) => a + r.exposures, 0);
    });
    return { hops, score: hops.reduce((a, h) => a + h.exposures, 0) };
  }
  const filt = on('minNecessary'), deid = on('deidentify'), consent = on('consentCheck');
  const R = run(filt, deid, consent), base = run(false, false, false).score;
  const hops = R.hops, fl = id => FIELDS.find(f => f.id === id).label.toLowerCase().replace(' id', ' ID');
  const list = ids => ids.length < 2 ? ids.join('') : ids.slice(0, -1).join(', ') + ' and ' + ids[ids.length - 1];
  const exposedIn = g => list(ALL.filter(f => g.cells[f].exposed).map(fl));
  const n = (k, w) => k + ' ' + w + (k === 1 ? '' : 's');
  function note(h, i) {
    const g = h.groups[0];
    if (i === 0) return 'The claims system pays the claim, so all 7 fields are needed here. Nothing is exposed.';
    if (h.gate) {
      const ok = h.groups.find(x => !x.optedOut), out = h.groups.find(x => x.optedOut);
      const a = ok.exposures ? 'Members 1 and 2 arrive with ' + n(ok.exposures, 'unneeded field') + '. ' : 'Members 1 and 2 arrive with only member ID and diagnosis. ';
      return a + (out.blocked ? 'The consent and BAA check stops Member 3, who opted out.' : 'Member 3 opted out, yet ' + n(out.exposures, 'field') + ' reach the vendor.');
    }
    if (h.analytics && filt && !deid) return 'Filtering keeps ' + exposedIn(g) + ' only to derive ' + h.derived + ': still ' + n(g.exposures, 'exposure') + ' per record.';
    const tok = ALL.some(f => g.cells[f].action === 'tokenised');
    if (!g.exposures) return (tok ? 'De-identified on arrival, so it' : 'Filtering means it') + ' receives only what its purpose needs. No exposure.';
    return (tok ? 'De-identified, but ' : 'Unneeded: ') + exposedIn(g) + (g.exposures === 1 ? ' still rides along' : ' ride along') + ', ' + n(g.exposures, 'exposure') + ' per record.';
  }
  const events = [];
  let t = 0;
  const add = (kind, hop, title, text, dur) => { events.push({ i: events.length, kind, hop, title, note: text, start: +t.toFixed(2), dur, checkAt: +(t + 0.55).toFixed(2), revealAt: +(t + 1.25).toFixed(2) }); t += dur; };
  add('intro', -1, 'A new use case asks for claims data', 'A product owner wants a readmission risk dashboard. Follow three claim records hop by hop.', 2.2);
  hops.forEach((h, i) => add('hop', i, (i + 1) + ' · ' + h.label, note(h, i), h.gate ? 3.2 : 2.7));
  const score = R.score;
  const worst = hops.reduce((a, h) => h.exposures > a.exposures ? h : a, hops[0]);
  const none = !filt && !deid && !consent;
  const summary = 'Exposure score ' + score + (none ? ' with every safeguard off' : ' (' + base + ' with no safeguards)') +
    (score ? '; most unneeded fields reach ' + worst.role + '.' : ': every hop gets only what its purpose needs.');
  add('finale', -1, 'Exposure score ' + score, summary, 3.4);
  let cum = 0;
  events.forEach(e => { if (e.kind === 'hop') cum += hops[e.hop].exposures; e.scoreAfter = cum; });
  const vend = hops[hops.length - 1].records.find(r => r.optedOut);
  return {
    fields: FIELDS, members: MEMBERS, hops, events, score, baseline: base,
    safeguards: { minNecessary: filt, deidentify: deid, consentCheck: consent }, systemNames: SF ? 'Salesforce' : 'Generic',
    optedOutReachesVendor: !vend.blocked,
    soWhat: 'Design minimum necessary into the pipeline, not the dashboard: filter at the first hand-off, de-identify before analytics, gate every export.',
    duration: +t.toFixed(2), markers: events.map(e => e.start), summary
  };
}

checkCode:
function check(p) {
  const m = model(p), keys = ['minNecessary', 'deidentify', 'consentCheck'];
  // 1. at every hop and for every record, exposures are exactly the fields present but not needed
  let setOk = true, total = 0;
  m.hops.forEach(h => h.records.forEach(r => {
    let k = 0;
    m.fields.forEach(f => { const c = r.cells[f.id], e = c.present && !c.needed; if (c.exposed !== e) setOk = false; if (e) k++; });
    if (k !== r.exposures) setOk = false;
    total += k;
  }));
  setOk = setOk && total === m.score;
  // 2. switching any one safeguard on never raises exposure, at any hop, whatever the other two are
  let comps = 0, mono = true;
  keys.forEach(k => [0, 1, 2, 3].forEach(c => {
    const others = keys.filter(x => x !== k), base = Object.assign({}, p, { [others[0]]: c & 1, [others[1]]: c >> 1 & 1 });
    const off = model(Object.assign({}, base, { [k]: 0 })), onm = model(Object.assign({}, base, { [k]: 1 }));
    comps++;
    if (onm.score > off.score || onm.hops.some((h, i) => h.exposures > off.hops[i].exposures)) mono = false;
  }));
  // 3. all three on leaves no exposure anywhere
  const all = model(Object.assign({}, p, { minNecessary: 1, deidentify: 1, consentCheck: 1 }));
  const zero = all.score === 0 && all.hops.every(h => h.exposures === 0);
  // 4. with the consent check on, the opted-out member never reaches the vendor
  const out = mm => mm.hops[mm.hops.length - 1].records.find(r => r.optedOut);
  const gateOk = [m, all].every(mm => !mm.safeguards.consentCheck || (out(mm).blocked && m.fields.every(f => !out(mm).cells[f.id].present)));
  const consent = m.safeguards.consentCheck;
  return {
    pass: setOk && mono && zero && gateOk,
    detail: 'Exposures equal present minus needed for all ' + m.hops.length * 3 + ' hop records (score ' + m.score + ' of ' + m.baseline +
      '), no safeguard raises exposure in ' + comps + ' on/off comparisons, all three on gives ' + all.score +
      ', and the opted-out member ' + (consent ? 'is blocked at the vendor gate.' : 'reaches the vendor only because the consent check is off.')
  };
}
